def allow_cancel(age_seconds, until_start_seconds) -> bool:
    if until_start_seconds < 0:
        return False
    elif until_start_seconds <= 24 * 3600:
        return True
    elif age_seconds < 10 * 60:  # 예약 생성부터 현재까지 10분 이내
        return True
    else:
        return False
```

